const items = $input.all();
const formData = items[0].json;

// ── number generation ──────────────────────────────────────────────────────
// The input includes all rows from Contratos sheet; count them to get next number
const existingCount = $('Leer Contratos').all().length;
const year = new Date().getFullYear();
const nextNum = String(existingCount + 1).padStart(3, '0');
const numContrato = `CONT-${year}-${nextNum}`;

// ── format date ────────────────────────────────────────────────────────────
const hoy = new Date();
const fechaHoy = hoy.toLocaleDateString('es-ES', {day: 'numeric', month: 'long', year: 'numeric'});

// ── empresa (PERSONALIZA ESTOS DATOS) ─────────────────────────────────────
const empresa = {
  nombre:    "TU EMPRESA S.L.",
  nif:       "B12345678",
  direccion: "Calle Ejemplo, 123",
  ciudad:    "28001 Madrid",
  email:     "info@tuempresa.com",
  telefono:  "+34 600 000 000",
};

// ── contrato HTML ──────────────────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Contrato ${numContrato}</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:Georgia,'Times New Roman',serif;font-size:11pt;color:#1a1a1a;background:#fff;line-height:1.6}
  .page{max-width:800px;margin:0 auto;padding:50px 60px}
  .header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #1e40af;padding-bottom:20px;margin-bottom:30px}
  .co-name{font-size:20pt;font-weight:700;color:#1e40af;font-family:system-ui,Arial,sans-serif}
  .co-info{font-size:9pt;color:#64748b;margin-top:6px;font-family:system-ui,Arial,sans-serif}
  .doc-title{text-align:right}
  .doc-title h1{font-size:18pt;color:#1a1a1a;font-family:system-ui,Arial,sans-serif}
  .doc-title p{font-size:10pt;color:#64748b;margin-top:4px;font-family:system-ui,Arial,sans-serif}
  .parties{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:24px 0;padding:20px;background:#f8fafc;border-radius:8px}
  .party h3{font-size:9pt;text-transform:uppercase;letter-spacing:.06em;color:#64748b;margin-bottom:8px;font-family:system-ui,Arial,sans-serif}
  .party p{font-size:10.5pt}
  .section{margin:24px 0}
  .section h2{font-size:11pt;font-weight:700;color:#1e40af;border-bottom:1px solid #e2e8f0;padding-bottom:6px;margin-bottom:12px;font-family:system-ui,Arial,sans-serif}
  .clause{margin:14px 0}
  .clause strong{font-size:10.5pt}
  .clause p{font-size:10.5pt;margin-top:4px}
  .signatures{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:60px}
  .sig-block{border-top:1px solid #1a1a1a;padding-top:8px}
  .sig-label{font-size:9pt;color:#64748b}
  .sig-name{font-size:10.5pt;font-weight:600;margin-top:4px}
  .footer{margin-top:40px;padding-top:12px;border-top:1px solid #e2e8f0;font-size:8.5pt;color:#94a3b8;text-align:center}
  .print-btn{position:fixed;top:16px;right:16px;background:#1e40af;color:white;border:none;padding:9px 20px;border-radius:8px;cursor:pointer;font-size:14px;font-family:system-ui,Arial,sans-serif}
  @media print{.print-btn{display:none}.page{padding:20px}}
</style>
</head>
<body>
<button class="print-btn" onclick="window.print()">🖨️ Imprimir / PDF</button>
<div class="page">
  <div class="header">
    <div>
      <div class="co-name">${empresa.nombre}</div>
      <div class="co-info">NIF: ${empresa.nif} · ${empresa.direccion}, ${empresa.ciudad}<br>${empresa.email} · ${empresa.telefono}</div>
    </div>
    <div class="doc-title">
      <h1>CONTRATO DE SERVICIOS</h1>
      <p>Nº ${numContrato}</p>
      <p>${fechaHoy}</p>
    </div>
  </div>

  <div class="parties">
    <div class="party">
      <h3>Prestador de Servicios</h3>
      <p><strong>${empresa.nombre}</strong><br>NIF: ${empresa.nif}<br>${empresa.direccion}<br>${empresa.ciudad}</p>
    </div>
    <div class="party">
      <h3>Cliente</h3>
      <p><strong>${formData['Nombre del Cliente']}</strong><br>NIF/CIF: ${formData['NIF o CIF del Cliente']}<br>Email: ${formData['Email del Cliente']}</p>
    </div>
  </div>

  <div class="section">
    <h2>Cláusulas del Contrato</h2>

    <div class="clause">
      <strong>PRIMERA – Objeto del Contrato</strong>
      <p>${formData['Descripcion del Servicio']}</p>
    </div>

    <div class="clause">
      <strong>SEGUNDA – Plazo de Ejecución</strong>
      <p>Los trabajos objeto del presente contrato se realizarán en el periodo comprendido entre el <strong>${formData['Fecha de Inicio']}</strong> y el <strong>${formData['Fecha de Fin']}</strong>.</p>
    </div>

    <div class="clause">
      <strong>TERCERA – Precio y Forma de Pago</strong>
      <p>El precio total acordado es de <strong>${parseFloat(formData['Valor Total EUR'] || 0).toLocaleString('es-ES', {minimumFractionDigits:2})} €</strong> (IVA no incluido), a pagar según las siguientes condiciones: ${formData['Condiciones de Pago'] || 'A convenir entre las partes'}.</p>
    </div>

    <div class="clause">
      <strong>CUARTA – Confidencialidad</strong>
      <p>Ambas partes se comprometen a mantener la más estricta confidencialidad respecto a la información intercambiada en el marco del presente contrato.</p>
    </div>

    <div class="clause">
      <strong>QUINTA – Ley Aplicable y Jurisdicción</strong>
      <p>El presente contrato se regirá por la legislación española. Las partes se someten a los juzgados y tribunales de ${empresa.ciudad.split(' ').slice(1).join(' ') || 'Madrid'}.</p>
    </div>
  </div>

  <div class="signatures">
    <div class="sig-block">
      <div class="sig-label">Por el prestador de servicios</div>
      <div class="sig-name">${empresa.nombre}</div>
      <div style="height:60px"></div>
      <div style="font-size:9pt;color:#64748b">Firma y sello</div>
    </div>
    <div class="sig-block">
      <div class="sig-label">Por el cliente</div>
      <div class="sig-name">${formData['Nombre del Cliente']}</div>
      <div style="height:60px"></div>
      <div style="font-size:9pt;color:#64748b">Firma</div>
    </div>
  </div>

  <div class="footer">Contrato generado el ${fechaHoy} · Referencia ${numContrato}</div>
</div>
</body>
</html>`;

return [{json: {html, numContrato, clienteNombre: formData['Nombre del Cliente'], fecha: new Date().toISOString().split('T')[0]}}];
